// Every DISTINCT handler the two tables between them install, defaults included. The
// registrar TU expands this to bind each original to its C++ reimplementation, so a handler
// that appears in the binary with no binding is a compile error rather than a silent gap.
//   X(original_symbol, cpp_stem)  -- cpp_stem is the original name minus the llm_strat_
//                                    prefix, which is the mh::sim wrapper's name for all 68.
#define MH_STATE_HANDLERS(X) \
    X(llm_strat_unit_state_default_noop, unit_state_default_noop) \
    X(llm_strat_unit_state_move_walker, unit_state_move_walker) \
    X(llm_strat_unit_state_stop_to_default, unit_state_stop_to_default) \
    X(llm_strat_unit_state_parked_noop, unit_state_parked_noop) \
    X(llm_strat_unit_state_group_marshal, unit_state_group_marshal) \
    X(llm_strat_unit_state_group_step, unit_state_group_step) \
    X(llm_strat_unit_state_enter_class_move, unit_state_enter_class_move) \
    X(llm_strat_unit_state_patrol_swap, unit_state_patrol_swap) \
    X(llm_strat_unit_state_plot_turn_path, unit_state_plot_turn_path) \
    X(llm_strat_unit_state_idle_scatter, unit_state_idle_scatter) \
    X(llm_strat_unit_state_takeoff_landing, unit_state_takeoff_landing) \
    X(llm_strat_unit_state_deploy_approach, unit_state_deploy_approach) \
    X(llm_strat_unit_state_deploy_to_building, unit_state_deploy_to_building) \
    X(llm_strat_unit_state_climb_vertical, unit_state_climb_vertical) \
    X(llm_strat_unit_state_descend_cruise, unit_state_descend_cruise) \
    X(llm_strat_unit_state_ascend_to_orbit, unit_state_ascend_to_orbit) \
